const regionSettledStats = `-- name: RegionSettledStats :many
SELECT n.region_id,
       COUNT(*)::int AS contracts_settled,
       COALESCE(SUM(c.quantity_delivered * c.unit_price), 0)::bigint AS trade_volume
FROM ledger.contracts c
JOIN world.network_nodes n ON n.id = c.destination_node_id
WHERE c.status = 'settled'
  AND c.settled_at_sim >= $1::bigint
  AND c.settled_at_sim <  $2::bigint
GROUP BY n.region_id
`

type RegionSettledStatsParams struct {
	BucketStart int64
	BucketEnd   int64
}

type RegionSettledStatsRow struct {
	RegionID         uuid.UUID
	ContractsSettled int32
	TradeVolume      int64
}

// RegionSettledStats agrega los contratos LIQUIDADOS del bucket por región,
// atribuidos por su NODO DE DESTINO (lado de consumo/entrega; atribución única
// que evita el doble conteo cuando origen y destino están en regiones distintas).
func (q *Queries) RegionSettledStats(ctx context.Context, arg RegionSettledStatsParams) ([]RegionSettledStatsRow, error) {
	rows, err := q.db.Query(ctx, regionSettledStats, arg.BucketStart, arg.BucketEnd)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RegionSettledStatsRow
	for rows.Next() {
		var i RegionSettledStatsRow
		if err := rows.Scan(&i.RegionID, &i.ContractsSettled, &i.TradeVolume); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

