const updateCityDemandCurve = `-- name: UpdateCityDemandCurve :exec
UPDATE world.city_demand
   SET supply_ema = $1::float8,
       saturation_factor = $2::float8,
       current_price = $3,
       recent_supply = 0,
       updated_at_sim = $4
 WHERE city_id = $5 AND product_id = $6
`

type UpdateCityDemandCurveParams struct {
	SupplyEma        float64
	SaturationFactor float64
	CurrentPrice     int64
	UpdatedAtSim     int64
	CityID           uuid.UUID
	ProductID        uuid.UUID
}

// UpdateCityDemandCurve escribe el resultado del recálculo de una (ciudad,
// producto): supply_ema (con suelo > 0), saturation_factor (acotado), el precio
// efectivo (ya clampado en [price_floor, price_ceiling]) y el sello de recálculo;
// RESETEA recent_supply a 0 (la ventana de oferta reciente arranca de nuevo).
func (q *Queries) UpdateCityDemandCurve(ctx context.Context, arg UpdateCityDemandCurveParams) error {
	_, err := q.db.Exec(ctx, updateCityDemandCurve,
		arg.SupplyEma,
		arg.SaturationFactor,
		arg.CurrentPrice,
		arg.UpdatedAtSim,
		arg.CityID,
		arg.ProductID,
	)
	return err
}

